  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸ਼ੇਖ ਫ਼ਰੀਦ ਜੀ ਦੇ ਦਿੱਤੇ ਗਏ ਸਲੋਕਾਂ ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਵਿਸਥਾਰ ਸਹਿਤ ਲਿਖੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਮਨੁੱਖੀ ਜੀਵਨ ਲਈ ਕਿਵੇਂ ਪ੍ਰੇਰਨਾਦਾਇਕ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਲੋਕ 'ਫਰੀਦਾ ਲੋੜੈ ਦਾਖ ਬਿਜਉਰੀਆਂ ਕਿਕਰਿ ਬੀਜੈ ਜਟੁ॥ ਹੰਢੈ ਊਨ ਕਤਾਇਦਾ ਪੈਧਾ ਲੋੜੈ ਪਟੁ॥' ਦੀ ਪ੍ਰਸੰਗ ਸਹਿਤ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਇਸ ਵਿੱਚ ਛੁਪੇ ਨੈਤਿਕ ਸੰਦੇਸ਼ ਨੂੰ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਲੋਕ 'ਫਰੀਦਾ ਰੁਖੀ ਸੁਖੀ ਖਾਇ ਕੈ ਠੰਡਾ ਪਾਣੀ ਪੀਉ॥ ਫਰੀਦਾ ਦੇਖਿ ਪਰਾਈ ਚੋਪੜੀ ਨਾ ਤਰਸਾਈ ਜੀਉ॥' ਦਾ ਵਿਸਥਾਰਪੂਰਵਕ ਅਰਥ ਲਿਖੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਸਲੋਕ ਅਜੋਕੇ ਸਮੇਂ ਵਿੱਚ ਕਿੰਨਾ ਕੁ ਪ੍ਰਸੰਗਿਕ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਲੋਕ 'ਫਰੀਦਾ ਜੇ ਤੂ ਅਕਲਿ ਲਤੀਫੁ ਕਾਲੇ ਲਿਖੁ ਨ ਲੇਖੁ॥ ਆਪਣੜੇ ਗਿਰੀਵਾਨ ਮਹਿ ਸਿਰੁ ਨੀਵਾਂ ਕਰਿ ਦੇਖੁ॥' ਦੀ ਵਿਆਖਿਆ ਕਰਦੇ ਹੋਏ ਆਤਮ-ਪੜਚੋਲ ਦੀ ਮਹੱਤਤਾ ਉੱਤੇ ਚਾਨਣਾ ਪਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਲੋਕ 'ਫਰੀਦਾ ਸਕਰ ਖੰਡੁ ਨਿਵਾਤ ਗੁੜੁ ਮਾਖਿਉ ਮਾਝਾ ਦੁਧੁ॥ ਸਭੇ ਵਸਤੂ ਮਿਠੀਆਂ ਰਬ ਨ ਪੁਜਨਿ ਤੁਧੁ॥' ਵਿੱਚ ਸ਼ੇਖ ਫ਼ਰੀਦ ਜੀ ਪ੍ਰਮਾਤਮਾ ਦੇ ਨਾਮ ਦੀ ਮਹੱਤਤਾ ਨੂੰ ਕਿਵੇਂ ਉਜਾਗਰ ਕਰਦੇ ਹਨ? ਵਿਸਥਾਰ ਸਹਿਤ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਲੋਕ 'ਬੁਢਾ ਹੋਆ ਸੇਖ ਫਰੀਦੁ ਕੰਬਣਿ ਲਗੀ ਦੇਹ॥ ਜੇ ਸਉ ਵਰ੍ਹਿਆ ਜੀਵਣਾ ਭੀ ਤਨੁ ਹੋਸੀ ਖੇਹ॥' ਦੀ ਪ੍ਰਸੰਗ ਸਹਿਤ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਮਨੁੱਖੀ ਸਰੀਰ ਦੀ ਨਾਸ਼ਵਾਨਤਾ ਬਾਰੇ ਸ਼ੇਖ ਫ਼ਰੀਦ ਜੀ ਦੇ ਵਿਚਾਰਾਂ ਨੂੰ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਲੋਕ 'ਫਰੀਦਾ ਜੋ ਤੈ ਮਾਰਨਿ ਮੁਕੀਆਂ ਤਿਨ੍ਹਾ ਨ ਮਾਰੇ ਘੁੰਮਿ॥ ਆਪਣੜੇ ਘਰਿ ਜਾਈਐ ਪੈਰ ਤਿਨ੍ਹਾ ਦੇ ਚੁੰਮਿ॥' ਦਾ ਵਿਸਥਾਰਪੂਰਵਕ ਅਰਥ ਲਿਖੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਸਲੋਕ ਖਿਮਾ ਅਤੇ ਨਿਮਰਤਾ ਦੇ ਗੁਣਾਂ ਨੂੰ ਕਿਵੇਂ ਉਭਾਰਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸ਼ੇਖ ਫ਼ਰੀਦ ਜੀ ਦੇ ਸਲੋਕਾਂ ਵਿੱਚ ਵਰਤੀ ਗਈ ਭਾਸ਼ਾ ਸ਼ੈਲੀ ਅਤੇ ਸ਼ਬਦਾਵਲੀ ਦੀ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਦਾ ਵਰਣਨ ਕਰੋ। ਔਖੇ ਸ਼ਬਦਾਂ ਦੇ ਅਰਥਾਂ ਦੀ ਸਹਾਇਤਾ ਨਾਲ ਉਦਾਹਰਣਾਂ ਦਿਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸ਼ੇਖ ਫ਼ਰੀਦ ਜੀ ਦੇ ਸਲੋਕਾਂ ਵਿੱਚ ਦਰਸਾਏ ਗਏ ਨੈਤਿਕ ਅਤੇ ਅਧਿਆਤਮਿਕ ਕਦਰਾਂ-ਕੀਮਤਾਂ ਦੀ ਚਰਚਾ ਕਰੋ। ਇਹ ਕਦਰਾਂ-ਕੀਮਤਾਂ ਅਜੋਕੇ ਸਮਾਜ ਲਈ ਕਿਵੇਂ ਲਾਹੇਵੰਦ ਹੋ ਸਕਦੀਆਂ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿੱਤੇ ਗਏ ਸਲੋਕਾਂ ਦੇ ਆਧਾਰ 'ਤੇ ਸ਼ੇਖ ਫ਼ਰੀਦ ਜੀ ਦੇ ਜੀਵਨ ਦਰਸ਼ਨ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਸੂਫੀ ਵਿਚਾਰਧਾਰਾ ਬਾਰੇ ਵਿਸਥਾਰਪੂਰਵਕ ਲੇਖ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('a199da29-8004-447e-9516-e77badca3504', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਰੀਦ-ਉਦ-ਦੀਨ ਮਸੂਦ ਗੰਜਸ਼ਕਰ (1173-1265 ਈ.) ਨੂੰ ਆਮ ਲੋਕ ਬਾਬਾ ਫਰੀਦ ਜਾਂ ਬਾਬਾ ਫਰੀਦ ਜੀ ਦੇ ਨਾਮ ਨਾਲ ਯਾਦ ਕਰਦੇ ਹਨ। ਉਹ ਬਾਰ੍ਹਵੀਂ ਸਦੀ ਦੇ ਚਿਸ਼ਤੀ ਸਿਲਸਿਲੇ ਦੇ ਸੂਫ਼ੀ ਸੰਤ ਅਤੇ ਪ੍ਰਚਾਰਕ ਸਨ। ਉਹਨਾਂ ਦਾ ਜਨਮ 1173 ਈ. ਵਿੱਚ ਮੁਲਤਾਨ (ਪਾਕਿਸਤਾਨ) ਤੋਂ ਦਸ ਕਿਲੋਮੀਟਰ ਦੂਰ ਪਿੰਡ ਕੋਠੇਵਾਲ ਵਿਖੇ ਹੋਇਆ ਸੀ। ਉਹਨਾਂ ਦੇ ਪਿਤਾ ਜੀ ਜਮਾਲ-ਉਦ-ਦੀਨ ਸੁਲੇਮਾਨ ਅਤੇ ਮਾਤਾ ਜੀ ਮਰੀਅਮ ਬੀਬੀ (ਕਰਸੂਮ ਬੀਬੀ) ਸਨ। ਉਹਨਾਂ ਨੂੰ ਪੰਜਾਬੀ ਬੋਲੀ ਦੇ ਆਦਿ ਕਵੀ ਵਜੋਂ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ। ਉਹਨਾਂ ਦੀ ਰਚਨਾ ਸ੍ਰੀ ਗੁਰੂ ਗ੍ਰੰਥ ਸਾਹਿਬ ਜੀ ਵਿੱਚ ਦਰਜ ਹੈ। ਸ੍ਰੀ ਗੁਰੂ ਗ੍ਰੰਥ ਸਾਹਿਬ ਜੀ ਵਿੱਚ ਉਹਨਾਂ ਦੇ ਚਾਰ (4) ਸ਼ਬਦ ਅਤੇ ਇੱਕ ਸੌ ਬਾਰ੍ਹਾਂ (112) ਸਲੋਕ ਦਰਜ ਹਨ। ਉਹਨਾਂ ਦੀ ਬਾਣੀ ਵਿੱਚਲੀ ਰੱਬ ਮਿਲਣ ਦੀ ਤਾਂਘ, ਨਿਮਰਤਾ, ਸਾਦਗੀ ਅਤੇ ਮਿਠਾਸ ਉਹਨਾਂ ਨੂੰ ਸਭ ਲੋਕਾਂ ਵਿੱਚ ਆਦਰ ਯੋਗ ਅਤੇ ਹਰਮਨ-ਪਿਆਰਾ ਬਣਾਉਂਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
