  ('bbbb09bd-1950-4712-87ef-5470b1cfaba9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਰੀਦਾ ਲੋੜੈ ਦਾਖ ਬਿਜਉਰੀਆਂ ਕਿਕਰਿ ਬੀਜੈ ਜਟੁ॥ ਹੰਢੈ ਊਨ ਕਤਾਇਦਾ ਪੈਧਾ ਲੋੜੈ ਪਟੁ॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('41ec208d-85fa-4308-9039-9abd0ce30508', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਰੀਦਾ ਰੁਖੀ ਸੁਖੀ ਖਾਇ ਕੈ ਠੰਡਾ ਪਾਣੀ ਪੀਉ॥ ਫਰੀਦਾ ਦੇਖਿ ਪਰਾਈ ਚੋਪੜੀ ਨਾ ਤਰਸਾਈ ਜੀਉ॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('85fc2fc0-7736-413e-a17f-4c91cf320dde', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਰੀਦਾ ਜੇ ਤੂ ਅਕਲਿ ਲਤੀਫੁ ਕਾਲੇ ਲਿਖੁ ਨ ਲੇਖੁ॥ ਆਪਣੜੇ ਗਿਰੀਵਾਨ ਮਹਿ ਸਿਰੁ ਨੀਵਾਂ ਕਰਿ ਦੇਖੁ॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ae8fb9fe-101d-4652-bb97-b135cf0d6e7e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਰੀਦਾ ਸਕਰ ਖੰਡੁ ਨਿਵਾਤ ਗੁੜੁ ਮਾਖਿਉ ਮਾਝਾ ਦੁਧੁ॥ ਸਭੇ ਵਸਤੂ ਮਿਠੀਆਂ ਰਬ ਨ ਪੁਜਨਿ ਤੁਧੁ॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d657c70a-9bf5-4fbd-81b0-e805f420d0dc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁਢਾ ਹੋਆ ਸੇਖ ਫਰੀਦੁ ਕੰਬਣਿ ਲਗੀ ਦੇਹ॥ ਜੇ ਸਉ ਵਰ੍ਹਿਆ ਜੀਵਣਾ ਭੀ ਤਨੁ ਹੋਸੀ ਖੇਹ॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('46c89de3-2e1f-4142-83d3-685726700a2b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਰੀਦਾ ਜੋ ਤੈ ਮਾਰਨਿ ਮੁਕੀਆਂ ਤਿਨ੍ਹਾ ਨ ਮਾਰੇ ਘੁੰਮਿ॥ ਆਪਣੜੇ ਘਰਿ ਜਾਈਐ ਪੈਰ ਤਿਨ੍ਹਾ ਦੇ ਚੁੰਮਿ॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d2d3dd32-41d4-4def-9f61-a54bfab9cc68', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਲੋਕ (ਸ਼ੇਖ ਫ਼ਰੀਦ ਜੀ) ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਸ਼ੇਖ ਫ਼ਰੀਦ ਜੀ ਦੇ ਸਲੋਕਾਂ ਬਾਰੇ ਜਾਣਕਾਰੀ ਪ੍ਰਦਾਨ ਕਰ ਕੇ ਚੰਗੇ ਕੰਮ ਕਰਨ ਦੀ ਪ੍ਰੇਰਨਾ ਦੇਣੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d5e5b60c-a280-4f61-b41e-d35af3b8cb64', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੋੜੈ - ਇੱਛਾ ਰੱਖਦਾ ਹੈ (wants), ਦਾਖ - ਛੋਟੇ ਅੰਗੂਰ (small grapes), ਬਿਜਉਰੀਆਂ-ਬਿਜੌਰ ਇਲਾਕੇ ਦੇ (related to Bijor region), ਪੈਧਾ - ਪਹਿਨਣਾ (wear), ਦੇਖਿ - ਵੇਖ ਕੇ (by seeing), ਅਕਲਿ ਲਤੀਫੁ - ਬਰੀਕ ਸਮਝ ਵਾਲਾ, ਸਮਝਦਾਰ (wise), ਗਿਰੀਵਾਨ - ਬੁੱਕਲ ਅੰਦਰ (within oneself), ਨਿਵਾਤ - ਮਿਸ਼ਰੀ (rock sugar), ਮਾਖਿਉ - ਸ਼ਹਿਦ (honey), ਨ ਪੁਜਨਿ - ਨਹੀਂ ਪਹੁੰਚਦੀਆਂ (do not reach), ਦੇਹ - ਸਰੀਰ, ਤਨ (body), ਸਉ ਵਰ੍ਹਿਆ - ਸੌ ਸਾਲ (hundred years), ਖੇਹ - ਸੁਆਹ, ਮਿੱਟੀ (ashes), ਘੁੰਮਿ - ਪਰਤ ਕੇ (in return)॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c55a814e-f2cc-47f5-abc1-1af6ae727d12', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '3b53afce-37c6-4242-88b3-8d84dec5a96c', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਫਰੀਦ-ਉਦ-ਦੀਨ ਮਸੂਦ ਗੰਜਸ਼ਕਰ (1173-1265 ਈ.) ਨੂੰ ਆਮ ਲੋਕ ਬਾਬਾ ਫਰੀਦ ਜਾਂ ਬਾਬਾ ਫਰੀਦ ਜੀ ਦੇ ਨਾਮ ਨਾਲ ਯਾਦ ਕਰਦੇ ਹਨ। ਉਹ ਬਾਰ੍ਹਵੀਂ ਸਦੀ ਦੇ ਚਿਸ਼ਤੀ ਸਿਲਸਿਲੇ ਦੇ ਸੂਫ਼ੀ ਸੰਤ ਅਤੇ ਪ੍ਰਚਾਰਕ ਸਨ। ਉਹਨਾਂ ਦਾ ਜਨਮ 1173 ਈ. ਵਿੱਚ ਮੁਲਤਾਨ (ਪਾਕਿਸਤਾਨ) ਤੋਂ ਦਸ ਕਿਲੋਮੀਟਰ ਦੂਰ ਪਿੰਡ ਕੋਠੇਵਾਲ ਵਿਖੇ ਹੋਇਆ ਸੀ। ਉਹਨਾਂ ਦੇ ਪਿਤਾ ਜੀ ਜਮਾਲ-ਉਦ-ਦੀਨ ਸੁਲੇਮਾਨ ਅਤੇ ਮਾਤਾ ਜੀ ਮਰੀਅਮ ਬੀਬੀ (ਕਰਸੂਮ ਬੀਬੀ) ਸਨ। ਉਹਨਾਂ ਨੂੰ ਪੰਜਾਬੀ ਬੋਲੀ ਦੇ ਆਦਿ ਕਵੀ ਵਜੋਂ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ। ਉਹਨਾਂ ਦੀ ਰਚਨਾ ਸ੍ਰੀ ਗੁਰੂ ਗ੍ਰੰਥ ਸਾਹਿਬ ਜੀ ਵਿੱਚ ਦਰਜ ਹੈ। ਸ੍ਰੀ ਗੁਰੂ ਗ੍ਰੰਥ ਸਾਹਿਬ ਜੀ ਵਿੱਚ ਉਹਨਾਂ ਦੇ ਚਾਰ (4) ਸ਼ਬਦ ਅਤੇ ਇੱਕ ਸੌ ਬਾਰ੍ਹਾਂ (112) ਸਲੋਕ ਦਰਜ ਹਨ। ਉਹਨਾਂ ਦੀ ਬਾਣੀ ਵਿੱਚਲੀ ਰੱਬ ਮਿਲਣ ਦੀ ਤਾਂਘ, ਨਿਮਰਤਾ, ਸਾਦਗੀ ਅਤੇ ਮਿਠਾਸ ਉਹਨਾਂ ਨੂੰ ਸਭ ਲੋਕਾਂ ਵਿੱਚ ਆਦਰ ਯੋਗ ਅਤੇ ਹਰਮਨ-ਪਿਆਰਾ ਬਣਾਉਂਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-53-777Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
